package app.layan.test;
import android.app.*;import android.content.*;import android.media.*;import android.os.*;import java.util.*;import java.lang.reflect.*;
import app.layan.quran.DhikrReminder;
/** Native alarm, selected intervals and lifecycle policies on the installed release. */
public final class DhikrRegression extends Instrumentation{
 Bundle args;int checks;StringBuilder report=new StringBuilder();Context c;SharedPreferences p,s;Class<?> actualReminder;
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 void check(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}
 void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 Object call(String n,Class<?>[] types,Object... a)throws Exception{Class<?> actual=actualReminder==null?c.getApplicationContext().getClass().getClassLoader().loadClass("app.layan.quran.DhikrReminder"):actualReminder;Method m=actual.getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(null,a);}
 Intent due(){return new Intent().setClassName(c,"app.layan.quran.DhikrAlarmReceiver").setAction("app.layan.quran.DHIKR_DUE").putExtra("next",s.getLong("next",0)).putExtra("token",s.getString("token",""));}
 void receive(Intent i){ui(()->{try{call("receive",new Class[]{Context.class,Intent.class},c,i);}catch(Exception e){throw new RuntimeException(e);}});}
 void enable(String interval){ui(()->p.edit().putString(DhikrReminder.INTERVAL,interval).putBoolean(DhikrReminder.ENABLED,true).putBoolean(DhikrReminder.SILENT,false).commit());}
 void accelerate(long delay){long n=SystemClock.elapsedRealtime()+delay;String t=UUID.randomUUID().toString();ui(()->{s.edit().putLong("next",n).putString("token",t).commit();PendingIntent pi=PendingIntent.getBroadcast(c,181201,due(),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);c.getSystemService(AlarmManager.class).setExactAndAllowWhileIdle(AlarmManager.ELAPSED_REALTIME_WAKEUP,n,pi);});}
 public void onStart(){Bundle out=new Bundle();try{c=getTargetContext();p=android.preference.PreferenceManager.getDefaultSharedPreferences(c);s=c.getSharedPreferences("layan_dhikr_schedule",0);out.putString("sameReminderClass",String.valueOf(DhikrReminder.class==c.getApplicationContext().getClass().getClassLoader().loadClass("app.layan.quran.DhikrReminder")));String mode=args==null?"policies":args.getString("mode","policies");
 if(mode.equals("denied")){ui(()->p.edit().putBoolean(DhikrReminder.ENABLED,false).commit());enable("5");check(!p.getBoolean(DhikrReminder.ENABLED,false),"Missing required permission keeps reminder off");check(s.getLong("next",0)==0,"Missing permission has no alarm");check(!(Boolean)call("mayPlay",new Class[]{Context.class},c),"Missing permission cannot start audio");}
 else if(mode.equals("change")){check(p.getBoolean(DhikrReminder.ENABLED,false),"Reminder was already enabled before changing interval");String old=s.getString("token","");ui(()->p.edit().putString(DhikrReminder.INTERVAL,args.getString("interval","10")).commit());check(!old.equals(s.getString("token","")),"Changing interval replaces active schedule");check(Math.abs(s.getLong("next",0)-SystemClock.elapsedRealtime()-DhikrReminder.intervalMillis(c))<5000,"Changed interval native deadline");}
 else if(mode.equals("inspect")){check(s.getLong("next",0)>SystemClock.elapsedRealtime(),"Next interval scheduled after playback");check(p.getBoolean(DhikrReminder.ENABLED,false),"Remains enabled");report.append("next remaining ms=").append(s.getLong("next",0)-SystemClock.elapsedRealtime());}
 else if(mode.equals("arm")){ui(()->p.edit().putBoolean(DhikrReminder.ENABLED,false).commit());enable(args.getString("interval","5"));long delay=Long.parseLong(args.getString("delay","0"));if(delay>0)accelerate(delay);check(s.getLong("next",0)>SystemClock.elapsedRealtime(),"Native alarm armed");out.putInt("ringer",c.getSystemService(AudioManager.class).getRingerMode());out.putInt("audioMode",c.getSystemService(AudioManager.class).getMode());out.putInt("interruptionFilter",c.getSystemService(NotificationManager.class).getCurrentInterruptionFilter());out.putLong("deadline",s.getLong("next",0));out.putString("token",s.getString("token",""));report.append("OS alarm armed; no visible activity; delay override=").append(delay);}
 else if(mode.equals("disable")){ui(()->p.edit().putBoolean(DhikrReminder.ENABLED,false).commit());check(s.getLong("next",0)==0,"Disabling clears deadline");}
 else {Activity a=startActivitySync(new Intent().setClassName(c,"app.layan.quran.LayanInfoActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();actualReminder=a.getApplication().getClass().getClassLoader().loadClass("app.layan.quran.DhikrReminder");out.putString("sameActivityApplication",String.valueOf(a.getApplication()==c.getApplicationContext()));out.putString("sameActivityReminderClass",String.valueOf(actualReminder==DhikrReminder.class));AudioManager audio=c.getSystemService(AudioManager.class);audio.setRingerMode(AudioManager.RINGER_MODE_NORMAL);
 // A resumed VM may already have an enabled five-minute alarm. Disable once
 // so this case measures a fresh user activation rather than its old deadline.
 ui(()->p.edit().putBoolean(DhikrReminder.ENABLED,false).commit());
 for(String v:new String[]{"5","10","15","20","30","60","180","360","720"}){enable(v);long expected=Long.parseLong(v)*60000L;check(DhikrReminder.intervalMillis(c)==expected,"Selected interval "+v);check(Math.abs(s.getLong("next",0)-SystemClock.elapsedRealtime()-expected)<5000,"Native deadline "+v);AlarmManager.AlarmClockInfo alarm=c.getSystemService(AlarmManager.class).getNextAlarmClock();check(alarm!=null&&Math.abs(alarm.getTriggerTime()-System.currentTimeMillis()-expected)<5000,"Doze-capable visible alarm deadline "+v);}
 check(!(Boolean)call("mayPlay",new Class[]{Context.class},c),"No audio while app is visible");String old=s.getString("token","");receive(due());check(!old.equals(s.getString("token","")),"Foreground due reschedules without sound");Intent stale=due();enable("5");String fresh=s.getString("token","");receive(stale);check(fresh.equals(s.getString("token","")),"Stale event ignored");
 ui(a::finish);for(int k=0;k<100;k++){waitForIdleSync();if(!(Boolean)call("visible",new Class[]{ }))break;SystemClock.sleep(200);}Field vf=c.getApplicationContext().getClass().getClassLoader().loadClass("app.layan.quran.DhikrReminder").getDeclaredField("VISIBLE");vf.setAccessible(true);check(!(Boolean)call("visible",new Class[]{ }),"Finished activities are not visible: "+vf.get(null));check((Boolean)call("mayPlay",new Class[]{Context.class},c),"Closed app permits playback");audio.setRingerMode(AudioManager.RINGER_MODE_VIBRATE);check(!(Boolean)call("mayPlay",new Class[]{Context.class},c),"Silent mode skips by default");ui(()->p.edit().putBoolean(DhikrReminder.SILENT,true).commit());check((Boolean)call("mayPlay",new Class[]{Context.class},c),"Explicit silent override permits sound");audio.setRingerMode(AudioManager.RINGER_MODE_NORMAL);ui(()->p.edit().putBoolean(DhikrReminder.ENABLED,false).commit());check(s.getLong("next",0)==0,"Disable cancels schedule");check(!(Boolean)call("mayPlay",new Class[]{Context.class},c),"Disabled cannot play");report.append("All nine intervals, foreground suppression, closed eligibility, stale token, silent override and cancellation checked.");}
 out.putString("result","PASS "+checks+" assertions");out.putString("report",report.toString());finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
